	var bark = mix( vec3f( 0.111932, 0.090842, 0.068478 ), vec3f( 0.371238, 0.323143, 0.246201 ), sat( blotch * 0.55 + plate * 0.25 + ( iv - 0.5 ) * 0.5 + yn * 0.15 ) );
