	let roots = smoothstep( 0.42, 0.05, y ) * smoothstep( 0.35, 0.6, rootN );
	bark = mix( bark, mix( vec3f( 0.042311, 0.027321, 0.015996 ), vec3f( 0.111932, 0.068478, 0.036889 ), rootN ), smoothstep( 0.5, 0.0, y ) * 0.85 );
